<?php require_once "../includes/auth.php";require_login("student");require_once "../config/db.php";$id=$_SESSION["user"]["id"];$stmt=$conn->prepare("SELECT a.*,c.course_code FROM attendance a JOIN courses c ON a.course_id=c.id WHERE a.student_id=? ORDER BY a.attendance_date DESC");$stmt->bind_param("i",$id);$stmt->execute();$rows=$stmt->get_result();$page_title="Attendance";$css_path="../assets/css/style.css";$js_path="../assets/js/main.js";require "../includes/header.php";?>
<div class="dashboard"><aside class="sidebar"><?php include "sidebar.php"; ?></aside><main class="dash-main"><h1>My Attendance</h1><div class="panel"><div class="table-wrap"><table><tr><th>Date</th><th>Course</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r["attendance_date"])?></td><td><?=e($r["course_code"])?></td><td><span class="badge"><?=e($r["status"])?></span></td></tr><?php endwhile;?></table></div></div></main></div><?php require "../includes/footer.php"; ?>